    static void Component(Dictionary<string,object> output){
        var ledger=new NavigationRetentionBudget();NavPagedList<long> bank=null,cold=null,pin=null;
        try{
            bank=Change(null,ledger,r=>Bank.Create(1,600,r));long initial=ledger.PhysicalBytes;Require(bank.Count==2412&&bank.Capacity==2560,"fixed ring shape");
            var empty=Bytes(bank,ledger);bank.Retain();pin=bank;
            for(int tick=1;tick<=601;tick++){var source=bank;int t=tick;bank=Change(bank,ledger,r=>Bank.Account(source,t,t*3,1+t%64,1+t%7,600,true,r));Equation(bank);}
            Require(bank[Bank.Accepted]==600&&bank[Bank.Count]==600&&bank[Bank.SaturationDrops]==1,"newest drop saturation");Require(empty.SequenceEqual(Bytes(pin,ledger)),"pinned bank immutable");pin.Release();pin=null;
            var same=bank;bank=Change(bank,ledger,r=>Bank.Account(same,601,1803,26,7,600,true,r));Require(bank[Bank.SaturationDrops]==1,"duplicate boundary");
            same=bank;bank=Change(bank,ledger,r=>Bank.Account(same,601,1803,26,7,5,true,r));Require(bank[Bank.Count]==5&&bank[Bank.Discarded]==595,"shrink preserves oldest");
            cold=Cold(Bytes(bank,ledger),ledger);Require(Bytes(bank,ledger).SequenceEqual(Bytes(cold,ledger)),"physical immediate bytes");
            for(int t=1;t<=5;t++){
                var c=Bank.First(bank);Require(c.Tick==t&&c.Prefix==t*3&&c.Budget==1+t%64&&c.Revision==1+t%7,"saved FIFO operands");
                same=bank;bank=Change(bank,ledger,r=>Bank.Promote(same,r));var before=cold;cold=Change(cold,ledger,r=>Bank.Promote(before,r));Equation(bank);Require(Bytes(bank,ledger).SequenceEqual(Bytes(cold,ledger)),"cold exact next");
            }
            same=bank;bank=Change(bank,ledger,r=>Bank.Account(same,602,1806,4,9,600,true,r));same=bank;bank=Change(bank,ledger,r=>Bank.Account(same,603,1809,4,9,600,false,r));Require(bank[Bank.Count]==0&&bank[Bank.Discarded]==596,"no demand purge");Equation(bank);
            // Walk every admitted allocation ordinal; a failed private fork must
            // leave both committed bytes and live physical charge unchanged.
            int appendSites=Refusals(bank,ledger,r=>Bank.Account(bank,604,1812,64,10,600,true,r));
            same=bank;bank=Change(bank,ledger,r=>Bank.Account(same,604,1812,64,10,600,true,r));int promoteSites=Refusals(bank,ledger,r=>Bank.Promote(bank,r));
            int captureSites=0,decodeSites=0;var wire=Bytes(bank,ledger);long live=ledger.PhysicalBytes;
            ledger.AllocationAdmission=_=>{captureSites++;return true;};try{Bytes(bank,ledger);}finally{ledger.AllocationAdmission=null;}
            ledger.AllocationAdmission=_=>{decodeSites++;return true;};try{Cold(wire,ledger).ReleaseStorage();}finally{ledger.AllocationAdmission=null;}
            for(int mode=0;mode<2;mode++)for(int fail=1;fail<=(mode==0?captureSites:decodeSites);fail++){
                int at=0;ledger.AllocationAdmission=_=>++at!=fail;bool refused=false;try{if(mode==0)Bytes(bank,ledger);else Cold(wire,ledger).ReleaseStorage();}catch(InvalidOperationException){refused=true;}finally{ledger.AllocationAdmission=null;}
                Require(refused,"wire allocation refusal "+mode+":"+fail);Require(ledger.PhysicalBytes==live&&ledger.HeldBytes==0&&ledger.ActiveScopes==0,"wire refusal ledger0 "+mode+":"+fail);Require(wire.SequenceEqual(Bytes(bank,ledger)),"wire refusal immutable source");
            }
            output["component"]=new{captureSites,decodeSites,status="PASS",initialPhysicalBytes=initial,rawLongCapacityBytes=20480,peak=ledger.PeakRetainedBytes,appendAllocationSites=appendSites,promoteAllocationSites=promoteSites,accepted=bank[Bank.Accepted],promoted=bank[Bank.Promoted],discarded=bank[Bank.Discarded],queued=bank[Bank.Count],saturationDrops=bank[Bank.SaturationDrops]};
        }finally{pin?.Release();bank?.ReleaseStorage();cold?.ReleaseStorage();Require(ledger.PhysicalBytes==0&&ledger.HeldBytes==0&&ledger.ActiveScopes==0,"terminal ledger zero");}
    }
    static int Refusals(NavPagedList<long> bank,NavigationRetentionBudget ledger,Func<INavStorageReservation,NavPagedList<long>> prepare){
        byte[] before=Bytes(bank,ledger);long physical=ledger.PhysicalBytes;int sites=0;
        Require(ledger.TryOpenScope(NavigationPreparationKind.Admission,1,0,out var probe),"probe scope");using(probe){ledger.AllocationAdmission=_=>{sites++;return true;};try{var next=prepare(probe.OwnedReservation());next.ReleaseStorage();}finally{ledger.AllocationAdmission=null;}}
        for(int ordinal=1;ordinal<=sites;ordinal++){int n=0;Require(ledger.TryOpenScope(NavigationPreparationKind.Admission,1,0,out var s),"refusal scope");using(s){ledger.AllocationAdmission=_=>++n!=ordinal;bool refused=false;try{var next=prepare(s.OwnedReservation());next.ReleaseStorage();}catch(InvalidOperationException){refused=true;}finally{ledger.AllocationAdmission=null;}Require(refused,"expected allocation refusal "+ordinal);}Require(ledger.PhysicalBytes==physical&&ledger.HeldBytes==0,"refusal ledger "+ordinal);Require(before.SequenceEqual(Bytes(bank,ledger)),"atomic refusal bytes");}return sites;
    }
}
